<?php
$pdo=db();$editId=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT);$query=trim((string)($_GET['q']??''));$edit=null;$items=[];$movements=[];
try{$stats=$pdo->query("SELECT COUNT(*) AS active_items,(SELECT COUNT(*) FROM school_inventory_items WHERE active=1 AND quantity_on_hand<=reorder_level) AS low_items,(SELECT COUNT(*) FROM school_inventory_movements WHERE movement_on=CURDATE()) AS today_moves FROM school_inventory_items WHERE active=1")->fetch();if($editId){$s=$pdo->prepare('SELECT * FROM school_inventory_items WHERE id=:id');$s->execute(['id'=>$editId]);$edit=$s->fetch()?:null;}$like='%'.$query.'%';$s=$pdo->prepare("SELECT * FROM school_inventory_items WHERE (:q='' OR item_code LIKE :code OR item_name LIKE :name OR category LIKE :category) ORDER BY active DESC,(quantity_on_hand<=reorder_level) DESC,item_name LIMIT 300");$s->execute(['q'=>$query,'code'=>$like,'name'=>$like,'category'=>$like]);$items=$s->fetchAll();$s=$pdo->prepare("SELECT m.*,i.item_code,i.item_name,i.unit,u.full_name FROM school_inventory_movements m JOIN school_inventory_items i ON i.id=m.item_id LEFT JOIN users u ON u.id=m.recorded_by WHERE (:q='' OR i.item_code LIKE :code OR i.item_name LIKE :name OR COALESCE(m.reference,'') LIKE :reference OR COALESCE(m.destination,'') LIKE :destination) ORDER BY m.movement_on DESC,m.id DESC LIMIT 300");$s->execute(['q'=>$query,'code'=>$like,'name'=>$like,'reference'=>$like,'destination'=>$like]);$movements=$s->fetchAll();}catch(Throwable $e){error_log('Inventory page failed: '.$e->getMessage());echo '<section class="panel settings-panel"><h1>Stores setup required</h1><p>An administrator should import <code>database/migrations/013_inventory.sql</code> into the school database, then reload this page.</p></section>';return;}
?>
<div class="page-heading"><div><div class="eyebrow">SCHOOL OPERATIONS</div><h1>Stores & supplies</h1><p class="subheading">Maintain stock balances and a dated, accountable history of every movement.</p></div></div>
<section class="stat-strip"><div><span>Active stock items</span><b><?= number_format((int)$stats['active_items']) ?></b></div><div><span>At or below reorder level</span><b><?= number_format((int)$stats['low_items']) ?></b></div><div><span>Movements today</span><b><?= number_format((int)$stats['today_moves']) ?></b></div><div><span>Stock balance</span><b>Ledger controlled</b></div></section>
<section class="panel info-panel academic-note"><h2>Keep balances auditable</h2><p>Enter opening stock as a Receipt. Use Issue for supplies sent to a department or class, Write-off for loss or damage, and Adjustment only to correct a counted balance. Corrections are recorded as new movements; movement history is not edited or deleted.</p></section>
<section class="panel settings-panel"><h2><?= $edit?'Edit stock item':'Add a stock item' ?></h2><form method="post" action="actions/inventory_item_save.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><?php if($edit): ?><input type="hidden" name="item_id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label>Item code<input name="item_code" required maxlength="40" value="<?= h($edit['item_code']??'') ?>" placeholder="e.g. STN-001"></label><label>Item name<input name="item_name" required maxlength="160" value="<?= h($edit['item_name']??'') ?>" placeholder="Exercise books"></label><label>Category<input name="category" required maxlength="80" value="<?= h($edit['category']??'') ?>" placeholder="Stationery, IT, cleaning"></label><label>Unit<input name="unit" required maxlength="30" value="<?= h($edit['unit']??'') ?>" placeholder="each, ream, litre"></label><label>Reorder level<input type="number" name="reorder_level" min="0" max="999999999.999" step="0.001" required value="<?= h($edit['reorder_level']??'0.000') ?>"></label><label class="full-width">Notes <span class="optional">Optional</span><input name="notes" maxlength="500" value="<?= h($edit['notes']??'') ?>"></label><?php if($edit): ?><label class="checkbox-label"><input type="checkbox" name="active" value="1" <?= $edit['active']?'checked':'' ?>> Active for new stock movements</label><?php endif; ?><button class="primary-button"><?= $edit?'Save item':'Add item' ?></button><?php if($edit): ?><a class="outline-button" href="?page=inventory">Cancel edit</a><?php endif; ?></form></section>
<?php if($items): ?><section class="panel settings-panel"><h2>Record a stock movement</h2><form method="post" action="actions/inventory_movement_save.php" class="inline-form fee-schedule-form"><?= csrf_field() ?><label>Stock item<select name="item_id" required><option value="">Select active item</option><?php foreach($items as $item): if($item['active']): ?><option value="<?= (int)$item['id'] ?>"><?= h($item['item_code'].' · '.$item['item_name'].' ('.$item['quantity_on_hand'].' '.$item['unit'].')') ?></option><?php endif; endforeach; ?></select></label><label>Movement type<select name="movement_type" class="inventory-movement-type" required><?php foreach(['Receipt','Issue','Write-off','Adjustment'] as $t): ?><option><?= h($t) ?></option><?php endforeach; ?></select></label><label class="inventory-direction-field" hidden>Adjustment direction<select name="direction"><option value="Increase">Increase</option><option value="Decrease">Decrease</option></select></label><label>Quantity<input type="number" name="quantity" min="0.001" max="999999999.999" step="0.001" required></label><label>Movement date<input type="date" name="movement_on" max="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d')) ?>" required></label><label class="inventory-receipt-field">Unit cost <span class="optional">Receipt only</span><input type="number" name="unit_cost" min="0" max="9999999999.99" step="0.01"></label><label class="inventory-receipt-field">Currency<select name="currency"><option value="">Not recorded</option><option>USD</option><option>ZiG</option></select></label><label>Supplier / reference <span class="optional">Optional</span><input name="reference" maxlength="100"></label><label class="inventory-issue-field">Issued to <span class="optional">Required for Issue</span><input name="destination" maxlength="160" placeholder="Department, class or staff member"></label><label class="full-width">Reason<input name="reason" required minlength="3" maxlength="255" placeholder="Purchase delivery, classroom supply, stock count correction…"></label><button class="primary-button">Save movement</button></form></section><?php endif; ?>
<section class="panel learners-panel"><form class="list-toolbar" method="get"><input type="hidden" name="page" value="inventory"><div class="search-box"><span>⌕</span><input name="q" value="<?= h($query) ?>" placeholder="Search item code, name or reference"></div><div class="toolbar-right"><button class="outline-button">Search</button><?php if($query!==''): ?><a class="outline-button" href="?page=inventory">Clear</a><?php endif; ?></div></form></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Stock register</h2><p><?= count($items) ?> items shown · maximum 300 per search · balances at or below reorder level are highlighted</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Item</th><th>Category</th><th>Balance</th><th>Reorder level</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($items as $i): $low=(float)$i['quantity_on_hand']<=(float)$i['reorder_level']; ?><tr><td><b><?= h($i['item_name']) ?></b><br><span class="muted-cell"><?= h($i['item_code']) ?> · <?= h($i['unit']) ?></span></td><td><?= h($i['category']) ?></td><td><?= $low?'<span class="consent-pill pending">':'' ?><?= h(number_format((float)$i['quantity_on_hand'],3)) ?><?= $low?'</span>':'' ?> <?= h($i['unit']) ?></td><td><?= h(number_format((float)$i['reorder_level'],3)) ?> <?= h($i['unit']) ?></td><td><span class="status-pill"><?= $i['active']?'Active':'Archived' ?></span></td><td><a class="outline-button compact-button" href="?page=inventory&edit=<?= (int)$i['id'] ?>">Edit</a></td></tr><?php endforeach; if(!$items): ?><tr><td colspan="6" class="empty-cell">No stock items match. Add an item above to start the register.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Stock movement history</h2><p>Latest 300 matches · positive quantities increase stock; negative quantities reduce it.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Date / item</th><th>Movement</th><th>Quantity change</th><th>Reference / destination</th><th>Reason / recorded by</th><th>Unit cost</th></tr></thead><tbody><?php foreach($movements as $m): ?><tr><td><?= h(date('d M Y',strtotime($m['movement_on']))) ?><br><span class="muted-cell"><?= h($m['item_code'].' · '.$m['item_name']) ?></span></td><td><?= h($m['movement_type']) ?></td><td class="<?= (float)$m['quantity_delta']<0?'muted-cell':'' ?>"><?= h(number_format((float)$m['quantity_delta'],3)) ?> <?= h($m['unit']) ?></td><td><?= h($m['reference']?:'—') ?><?= $m['destination']?'<br>'.h($m['destination']):'' ?></td><td><?= h($m['reason']) ?><br><span class="muted-cell"><?= h($m['full_name']??'Former staff') ?></span></td><td><?= $m['unit_cost']!==null?h(number_format((float)$m['unit_cost'],2).' '.$m['currency']):'—' ?></td></tr><?php endforeach; if(!$movements): ?><tr><td colspan="6" class="empty-cell">No stock movements have been recorded.</td></tr><?php endif; ?></tbody></table></div></section>
<script>document.querySelectorAll('.inventory-movement-type').forEach(function(type){const form=type.closest('form'),direction=form.querySelector('.inventory-direction-field'),receipt=form.querySelectorAll('.inventory-receipt-field'),issue=form.querySelector('.inventory-issue-field input');function update(){direction.hidden=type.value!=='Adjustment';receipt.forEach(x=>x.hidden=type.value!=='Receipt');issue.required=type.value==='Issue'}type.addEventListener('change',update);update()});</script>
